import androidx.compose.animation.core.RepeatMode
import androidx.compose.animation.core.animateFloat
import androidx.compose.animation.core.infiniteRepeatable
import androidx.compose.animation.core.rememberInfiniteTransition
import androidx.compose.animation.core.tween
import androidx.compose.foundation.background
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.runtime.getValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.composed
import androidx.compose.ui.draw.clip
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.dp

fun Modifier.skeleton(
    visible: Boolean,
    depthLevel: Int = 0 // Nivel de profundidad (0 = base, 1 = hijo, 2 = nieto, etc.)
): Modifier {
    val colors = when (depthLevel) {
        0 -> listOf(Color(0xFFCBCBCB), Color(0xFFF5F5F5), Color(0xFFB7B6B6)) // Nivel 1 - más claro
        1 -> listOf(Color(0xFFA0A0A0), Color(0xFFD0D0D0), Color(0xFF808080)) // Nivel 2 - medio
        else -> listOf(Color(0xFF606060), Color(0xFF909090), Color(0xFF404040)) // Nivel 3+ - más oscuro
    }

    return if (visible) {
        this
            .clip(RoundedCornerShape(12.dp))
            .shimmerEffect(colors = colors)
    } else {
        this
    }
}


fun Modifier.shimmerEffect(colors: List<Color>): Modifier = composed {

    val transition = rememberInfiniteTransition(label = "shimmer")
    val translateAnim by transition.animateFloat(
        initialValue = -1000f,
        targetValue = 1000f,
        animationSpec = infiniteRepeatable(
            animation = tween(2900),
            repeatMode = RepeatMode.Restart
        ),
        label = "shimmerAnim"
    )

    background(
        brush = Brush.linearGradient(
            colors = colors,
            start = Offset.Zero,
            end = Offset(translateAnim, translateAnim)
        )
    )
}
